INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_HTH.M_TV_NUMBER_UP_TO_DIGIT', 'MATH.G5.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_HTH', 'Gives the number formed by all the digits from the left up to the digit asked about, instead of that digit''s own total value.', '{"question":"How much is the digit 1 worth in 661,125?","wrong_answer":"661,100","correct_answer":"100"}'::jsonb, 'The child reads the number up to the place and fills the rest with zeros, as if rounding, so the digits to the left are counted too.', 'A total-value item with the rounded-down number among the choices.', 'Cover every digit except the one asked about. Write that digit and the zeros that follow it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.WHOLE_NUMBERS.NUMBERS_TO_WORDS.M_WORDS_THOUSANDS_AS_HUNDREDS', 'MATH.G5.NUMBER.WHOLE_NUMBERS.NUMBERS_TO_WORDS', 'Reads the first two digits of a five-digit number as hundreds (''twenty-five hundred''), so the thousands group is called hundreds.', '{"question":"Which of these is 25,068 written in words?","wrong_answer":"twenty-five hundred and sixty-eight","correct_answer":"twenty-five thousand and sixty-eight"}'::jsonb, 'The child has met ''hundred'' for the third place and reads any large number as a count of hundreds, without grouping the digits in threes.', 'A numbers-to-words item with a ''hundred'' reading of the thousands group among the choices.', 'Cover the last three digits and read the rest with the word thousand: twenty-five thousand. Then read the last three digits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.WHOLE_NUMBERS.NUMBERS_TO_WORDS.M_WORDS_THOUSAND_WORD_MISSING', 'MATH.G5.NUMBER.WHOLE_NUMBERS.NUMBERS_TO_WORDS', 'Writes the thousands group and the rest of the number without saying ''thousand''.', '{"question":"Which of these is 25,068 written in words?","wrong_answer":"twenty-five, sixty-eight","correct_answer":"twenty-five thousand and sixty-eight"}'::jsonb, 'The child reads the digits in two chunks and forgets that the comma stands for the word thousand.', 'A numbers-to-words item where one choice leaves out the word thousand.', 'Point at the comma and say ''thousand'' out loud every time you pass it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.WHOLE_NUMBERS.WORDS_TO_SYMBOLS.M_SYMBOLS_STOPS_AT_THOUSAND', 'MATH.G5.NUMBER.WHOLE_NUMBERS.WORDS_TO_SYMBOLS', 'Writes only the thousands part of a number given in words and leaves out the rest.', '{"question":"Write ninety-one thousand and sixty-seven in figures.","wrong_answer":"91000","correct_answer":"91067"}'::jsonb, 'The child writes the first big word group as a finished number and does not go on to the words that follow it.', 'A words-to-symbols item with the thousands part alone among the choices.', 'Tick each part of the words as it is written: ninety-one thousand, and, sixty-seven.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.FRACTIONS.EQUIVALENT_FRACTIONS.M_EQUIV_FEWER_PIECES_BIGGER', 'MATH.G5.NUMBER.FRACTIONS.EQUIVALENT_FRACTIONS', 'Thinks the fraction with fewer pieces (the smaller bottom number) is the bigger amount, even when the other fraction has more of the smaller pieces.', '{"question":"Juma ate 2/3 of a chapati. Chebet ate 8/12 of an equal chapati. Who ate more?","wrong_answer":"Juma, because 2/3 has fewer pieces","correct_answer":"They ate the same amount"}'::jsonb, 'The child has learned that 1/3 is bigger than 1/12 and stretches it to every fraction: fewer pieces always means bigger pieces, so a bigger share.', 'A comparison of two fractions where the one with the smaller bottom number is not the bigger amount.', 'Fold two equal strips: one into 3, one into 12. Shade 2 thirds and 8 twelfths and lay them side by side. Fewer pieces means each piece is bigger, but Chebet has more pieces.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.FRACTIONS.SIMPLIFY_FRACTIONS.M_FRACTION_UPSIDE_DOWN', 'MATH.G5.NUMBER.FRACTIONS.SIMPLIFY_FRACTIONS', 'Writes the fraction upside down, with the whole (or the total) on top and the part on the bottom.', '{"question":"Ochieng ate 30 of the 36 mandazi. What fraction was eaten, in its simplest form?","wrong_answer":"6/5","correct_answer":"5/6"}'::jsonb, 'The child divides the numbers correctly but does not hold that the part goes on top (numerator) and the whole on the bottom (denominator).', 'A word problem asking for the fraction eaten or used, with the upside-down fraction among the choices.', 'Say it aloud: 30 out of 36. The ''out of'' number, the whole, goes on the bottom. A fraction of a whole is never more than 1 when it is a part.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.FRACTIONS.SIMPLIFY_FRACTIONS.M_SIMPLEST_BY_LOOKS', 'MATH.G5.NUMBER.FRACTIONS.SIMPLIFY_FRACTIONS', 'Judges a fraction to be in its simplest form from how it looks (top smaller than bottom, a proper fraction) without looking for a common factor.', '{"question":"Is 6/8 in its simplest form?","wrong_answer":"Yes, because 6 is smaller than 8","correct_answer":"No. Both divide by 2, giving 3/4"}'::jsonb, 'The child confuses ''proper fraction'' with ''simplest form'' and treats any fraction less than one as already simple.', 'A yes or no question on whether a fraction is in simplest form, with a reason based on size.', 'Ask for a number that divides both the top and the bottom. If one exists other than 1, the fraction is not simplest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.FRACTIONS.COMPARE_LIKE_FRACTIONS.M_COMPARE_MATCHING_PART_EQUAL', 'MATH.G5.NUMBER.FRACTIONS.COMPARE_LIKE_FRACTIONS', 'Sees one matching number (the same top, or the same bottom) and decides the two fractions are equal.', '{"question":"Kioko takes 1 piece of a chapati cut into 4 equal pieces. Asha takes 1 piece of the same size of chapati cut into 5. Whose piece is bigger?","wrong_answer":"They are the same size, each took one piece","correct_answer":"Kioko''s piece"}'::jsonb, 'The child counts the pieces taken (''one each'') and ignores how many pieces the whole was cut into.', 'A comparison where the tops match or the bottoms match and the child answers ''equal''.', 'Cut two paper circles, one into 4 and one into 5, and lay the single pieces on top of each other.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.FRACTIONS.COMPARE_LIKE_FRACTIONS.M_COMPARE_SYMBOL_REVERSED', 'MATH.G5.NUMBER.FRACTIONS.COMPARE_LIKE_FRACTIONS', 'Understands which fraction is bigger but writes the wrong way round, mixing up the symbols < and >.', '{"question":"Compare 4/7 and 6/7. Which symbol makes 4/7 ___ 6/7 true?","wrong_answer":">","correct_answer":"<"}'::jsonb, 'The child knows 6/7 is bigger but has not fixed that the open side of the sign faces the bigger number.', 'A symbol question where the child''s explanation is right and the symbol is the wrong one.', 'Ask the child to say the sentence in words: ''4/7 is less than 6/7''. The sign opens towards the bigger number, like a hungry mouth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.FRACTIONS.ADD_SAME_DENOMINATOR.M_MISSING_ADDEND_ADDED', 'MATH.G5.NUMBER.FRACTIONS.ADD_SAME_DENOMINATOR', 'In a missing-number sum, adds the numbers that are shown instead of subtracting to find the missing one.', '{"question":"Find the missing numerator: 2/8 + ?/8 = 5/8.","wrong_answer":"7","correct_answer":"3"}'::jsonb, 'The child sees two numbers and a plus sign and adds them, without asking what must be added to reach the total.', 'A missing-addend question where the sum of the two shown tops is among the choices.', 'Use cut-out eighths: 2 pieces on the table and 5 needed. How many more pieces must you add?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.FRACTIONS.ADD_SAME_DENOMINATOR.M_MISSING_PICKS_SHOWN_NUMBER', 'MATH.G5.NUMBER.FRACTIONS.ADD_SAME_DENOMINATOR', 'In a missing-number fraction sentence, picks a number that is already shown (the total or the result) instead of working out the missing one.', '{"question":"Find the missing numerator: 2/8 + ?/8 = 5/8.","wrong_answer":"5","correct_answer":"3"}'::jsonb, 'The child looks for the number that seems to belong in the gap and copies the one after the equals sign, as ''the answer''.', 'A missing-numerator question with the total or the result among the choices.', 'Put the answer back into the sum: does 2/8 + 5/8 make 5/8?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.FRACTIONS.SUBTRACT_SAME_DENOMINATOR.M_SUB_DROPS_DENOMINATOR', 'MATH.G5.NUMBER.FRACTIONS.SUBTRACT_SAME_DENOMINATOR', 'Subtracts the numerators and writes the answer as a whole number, dropping the denominator.', '{"question":"Hassan ate 1/10 of a pawpaw. What fraction is left?","wrong_answer":"9","correct_answer":"9/10"}'::jsonb, 'The child does the subtraction on the tops, 10 − 1, and forgets that the answer is a part of the pawpaw, counted in tenths.', 'A take-away story where the answer is a whole number with no bottom number.', 'Say it as tenths: 10 tenths take away 1 tenth is 9 tenths. Nine pawpaws would be a lot of fruit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.FRACTIONS.SUBTRACT_SAME_DENOMINATOR.M_SUB_DONE_AS_ADDITION', 'MATH.G5.NUMBER.FRACTIONS.SUBTRACT_SAME_DENOMINATOR', 'Adds the numbers when the story takes something away.', '{"question":"Hassan ate 1/10 of a pawpaw. What fraction is left?","wrong_answer":"11/10","correct_answer":"9/10"}'::jsonb, 'The child sees two fractions and combines them, without picturing what happens to the pawpaw. An answer greater than one whole does not alarm them.', 'A take-away problem where the sum of the two numbers is among the choices.', 'Draw the pawpaw. Eating takes a piece away, so there must be fewer pieces than before.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.FRACTIONS.SUBTRACT_SAME_DENOMINATOR.M_SUB_ONE_STEP_ONLY', 'MATH.G5.NUMBER.FRACTIONS.SUBTRACT_SAME_DENOMINATOR', 'In a two-step take-away, subtracts only the first amount and forgets the second.', '{"question":"A tank holds 7/8. 2/8 is used on Monday and 1/8 on Tuesday. What is left?","wrong_answer":"5/8","correct_answer":"4/8, which is 1/2"}'::jsonb, 'The child stops after the first subtraction because the first answer looks like a finished answer.', 'A table or story with two amounts taken away, with the answer after one subtraction among the choices.', 'Tick each line of the table as it is used. Every ''used'' line must be taken away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.DECIMALS.DEC_PLACE_NAME.M_PLACE_OFF_BY_ONE', 'MATH.G5.NUMBER.DECIMALS.DEC_PLACE_NAME', 'Counts the decimal places from the wrong starting point, so names the place next to the right one (calls the hundredths place the tenths, or the other way round).', '{"question":"In 7.698, the digit 6 is in which place?","wrong_answer":"hundredths","correct_answer":"tenths"}'::jsonb, 'The child starts counting at the digit next to the point as ''0'', or counts the point itself as a place, so every name is one step out.', 'A question naming a digit''s place, with the neighbouring place among the choices.', 'Touch the point and say ''the first place after the point is tenths''. Then count to the right one place at a time: tenths, hundredths, thousandths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.DECIMALS.DEC_PLACE_NAME.M_SAME_DIGIT_SAME_VALUE', 'MATH.G5.NUMBER.DECIMALS.DEC_PLACE_NAME', 'Says 2 tenths and 2 hundredths are equal because the digit is the same, ignoring the size of the place.', '{"question":"Which is more, 2 tenths or 2 hundredths?","wrong_answer":"They are the same","correct_answer":"2 tenths is more"}'::jsonb, 'The child reads the digit and ignores the place name, so only the number 2 counts and the size of the pieces is not thought about.', 'A comparison of the same digit in two different places, with ''the same'' among the choices.', 'Shade 2 strips of a tenths bar and 2 small squares of a hundredths grid side by side. The same digit, but a very different amount.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.DECIMALS.DEC_DIGIT_VALUE.M_PLACES_SWAPPED', 'MATH.G5.NUMBER.DECIMALS.DEC_DIGIT_VALUE', 'Writes the digits in the wrong columns, for example the thousandths digit before the hundredths digit, when writing a decimal from words.', '{"question":"Write as a decimal: 6 ones, 0 tenths, 5 hundredths and 7 thousandths.","wrong_answer":"6.075","correct_answer":"6.057"}'::jsonb, 'The child writes the digits in the order they feel natural (the bigger digit first) and does not match each digit to its column.', 'A write-the-decimal-from-words question with a swapped-digit option.', 'Draw a chart with the four headings. Say each phrase and put its digit in the column of the same name before writing the number.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.DECIMALS.DEC_ORDER.M_ORDER_DIRECTION_REVERSED', 'MATH.G5.NUMBER.DECIMALS.DEC_ORDER', 'Writes the decimals largest first when asked to arrange them from smallest, or the other way round.', '{"question":"Arrange from smallest to largest: 7.05, 6.875, 6.9.","wrong_answer":"7.05, 6.9, 6.875","correct_answer":"6.875, 6.9, 7.05"}'::jsonb, 'The child compares the decimals correctly but mixes up which end the order starts from.', 'An ordering question where the right order backwards is among the choices.', 'Say the first number out loud and ask ''is this the smallest of all?'' before writing it down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.DECIMALS.DEC_SUB_SAME_PLACES.M_SUB_DONE_AS_ADDITION', 'MATH.G5.NUMBER.DECIMALS.DEC_SUB_SAME_PLACES', 'Adds the two decimals when the story takes one away (used, sold, leaks out).', '{"question":"A roll of cloth was 3.15 m long and 1.43 m was used. How much is left?","wrong_answer":"4.58","correct_answer":"1.72"}'::jsonb, 'The child sees two decimals and combines them, without picturing what happens in the story. An answer bigger than the roll does not alarm them.', 'A take-away story where the sum of the two decimals is among the choices.', 'Draw the cloth. Cutting off a piece leaves less cloth than before, so the answer must be smaller than the whole roll.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_MEANING.M_LETTER_IS_GIVEN_NUMBER', 'MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_MEANING', 'Takes the letter to stand for a number already printed in the equation (the total, or the number being added), not for the unknown number.', '{"question":"In n + 5 = 25, n is the cost of one pencil. What does n stand for?","wrong_answer":"The total, 25 shillings","correct_answer":"The cost of one pencil, a number we do not know yet"}'::jsonb, 'The child looks for a number to attach the letter to and picks the biggest or the last one written, because the unknown has no number of its own to point at.', 'A question asking what a letter stands for, with a number from the equation among the choices.', 'Cover the letter with a closed hand. Ask ''Which number is hidden?'' The 25 and the 5 can both be seen, so the hidden one must be a different number.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_MEANING.M_LETTER_ANY_NUMBER', 'MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_MEANING', 'Thinks the letter can be any number at all, so it has no one value in this equation (''n can be anything'').', '{"question":"In n + 5 = 25, n is the cost of one pencil. What does n stand for?","wrong_answer":"Any number we like, it changes each time","correct_answer":"One number we do not know yet, the cost of the pencil"}'::jsonb, 'The child has seen letters used for patterns and rules, where a letter can take many values, and has not yet met a letter that is one fixed unknown.', 'A question asking what a letter stands for, where one choice says the letter can be any number.', 'Show that 3 + 5 = 25 is false and 20 + 5 = 25 is true: only one number keeps the balance level.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_FORM_ADD_SUB.M_OPERATION_OPPOSITE_TO_STORY', 'MATH.G5.NUMBER.SIMPLE_EQUATIONS.EQ_FORM_ADD_SUB', 'Writes the opposite operation to the one in the story: plus for something taken away, or minus for something added.', '{"question":"Njeri had some shillings. She spent sh 78 and had sh 132 left. Which equation fits?","wrong_answer":"m + 78 = 132","correct_answer":"m − 78 = 132"}'::jsonb, 'The child is thinking ahead to the working (the inverse) and writes that, instead of writing what happened in the story, step by step.', 'A story-to-equation question where one option uses the opposite sign to the story.', 'Act the story with coins: start with a heap, take 78 away. Say what happened in order, then write it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
